"""Синтетический комплект «Ренессанса» для тестов без data/raw/: договор + «Приложение 1. Программа ДМС».

Повторяет устройство ГК 2 (docs/facts/kit/gk2.md) в миниатюре: номера пунктов текстом, таблица п. 2.3, график
взносов п. 2.7; в программе — перечень клиник с протяжкой юрлица, VML-иконкой «по записи», примечанием «^^^^^»,
франшизой в названии, легендой иконок; текст условий одной ячейкой; вторая программа «Бета» начинается внутри
таблицы с текстом первой (ловушка «Калининград/Пермь»); «Расширения к холдингу» в конце. Все тексты выдуманы.
"""
from __future__ import annotations

import struct
import zlib
from pathlib import Path

from docx import Document
from docx.oxml import parse_xml

from dms_core.kit import KitContract, KitFile

_VML = ('<w:p xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" '
        'xmlns:v="urn:schemas-microsoft-com:vml" '
        'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'
        '<w:r><w:pict><v:shape style="width:9pt;height:9pt"><v:imagedata r:id="{rid}"/></v:shape></w:pict></w:r>'
        '</w:p>')


def _png(rgb: tuple[int, int, int]) -> bytes:
    """PNG 1×1 нужного цвета (разные цвета → разные sha1 → разные маркеры иконок)."""
    def chunk(tag: bytes, data: bytes) -> bytes:
        return struct.pack(">I", len(data)) + tag + data + struct.pack(">I", zlib.crc32(tag + data) & 0xFFFFFFFF)
    raw = b"\x00" + bytes(rgb)
    return (b"\x89PNG\r\n\x1a\n" + chunk(b"IHDR", struct.pack(">IIBBBBB", 1, 1, 8, 2, 0, 0, 0))
            + chunk(b"IDAT", zlib.compress(raw)) + chunk(b"IEND", b""))


def _icon(doc, cell, png: Path) -> None:
    rid, _ = doc.part.get_or_add_image(str(png))
    cell._tc.append(parse_xml(_VML.format(rid=rid)))


FILLER = ("Медицинская помощь оказывается в медицинских организациях, указанных в Программе, по предварительной "
          "записи через круглосуточный медицинский пульт Страховщика. ")


def build(tmp: Path) -> tuple[KitContract, Path]:
    """Создаёт «ГК 9/Компания 99/…» в tmp и возвращает опись договора c99 и корень."""
    folder = tmp / "ГК 9" / "Компания 99"
    folder.mkdir(parents=True, exist_ok=True)
    icon_r, icon_n = tmp / "r.png", tmp / "n.png"
    icon_r.write_bytes(_png((200, 0, 0)))
    icon_n.write_bytes(_png((0, 0, 200)))

    # ---------------- договор
    d = Document()
    for t in ("ДОГОВОР № 99", "добровольного медицинского страхования", "24 апреля 2026 г.",
              ('ПАО "Группа Ренессанс Страхование", именуемое в дальнейшем «Страховщик», и ООО "КОМПАНИЯ 99" '
              "заключили настоящий Договор."),
              "1. ПРЕДМЕТ ДОГОВОРА",
              ("1.1.  Страховщик обязуется оплатить услуги. Общая численность Застрахованных лиц на дату заключения "
              "Договора составляет 3 (Три) человека."),
              "2.3.\tРазмеры страховой суммы и страховой премии за срок действия Договора:"):
        d.add_paragraph(t)
    tb = d.add_table(rows=3, cols=5)
    for r, vals in enumerate([
        ("Название Программы", "Страховая премия за одно Застрахованное лицо", "Страховая сумма",
         "Страховая сумма по программе «Медикаментозное обеспечение»", "Количество\nЗастрахованных лиц"),
        ("Альфа", "100,00", "1\xa0000\xa0000,00", "3\xa0000,00", "2"),
        ("Бета", "50,00", "900\xa0000,00", "", "1"),
    ]):
        for c, v in enumerate(vals):
            tb.cell(r, c).text = v
    for t in (("2.4.\tОбщая страховая премия по Договору составляет 250,00 (Двести пятьдесят рублей 00 копеек) "
              "рублей."),
              "2.7.\tСтраховая премия уплачивается Страхователем в рассрочку в следующем порядке:",
              ("Страховой взнос за период с 25.04.2026 г. по 24.10.2026 г. в размере 125,00 (Сто двадцать пять "
              "рублей) рублей уплачивается до 25.05.2026 г."),
              ("Страховой взнос за период с 25.10.2026 г. по 24.04.2027 г. в размере 125,00 (Сто двадцать пять "
              "рублей) рублей уплачивается до 25.11.2026 г."),
              "2.13. Франшиза (безусловная) указывается в Программе страхования.",
              "3.4.5.\tПо согласованию со Страховщиком включать в список родственников, при этом:",
              "1)\tк родственникам относятся: супруга, супруг, дети.",
              "2)\tстрахование родственников осуществляется в течение 2 (двух) месяцев.",
              "4.1.\tНастоящий Договор заключен на срок с 25 апреля 2026 г. по 24 апреля 2027 г.",
              "7.1.\tВнесение изменений в списки прекращается за 2 (два) месяца до окончания Договора."):
        d.add_paragraph(t)
    d.save(folder / "Договор № 99.docx")

    # ---------------- программа
    p = Document()
    p.add_paragraph("ПРИЛОЖЕНИЕ N1")
    p.add_paragraph("ПРОГРАММА ДОБРОВОЛЬНОГО МЕДИЦИНСКОГО СТРАХОВАНИЯ")

    def one(table, text):
        """Одноячеечная строка; каждая строка текста — отдельный абзац ячейки (как в документах ГК 2)."""
        row = table.add_row()
        cell = row.cells[0].merge(row.cells[-1])
        lines = text.split("\n")
        cell.text = lines[0]
        for line in lines[1:]:
            cell.add_paragraph(line)

    def clinic(table, org, icon, addr, code):
        row = table.add_row()
        for c, v in enumerate((org, "", addr, code)):
            row.cells[c].text = v
        if icon:
            _icon(p, row.cells[1], icon_r)

    def legend(table):
        one(table, "Обслуживание в этом лечебном учреждении осуществляется:")
        row = table.add_row()
        row.cells[1].text = 'по предварительной записи по направлению врача ООО "Ренессанс Здоровье"'
        row.cells[3].text = "по записи через центр медицинского обслуживания «Ренессанс страхование»"
        _icon(p, row.cells[0], icon_n)
        _icon(p, row.cells[2], icon_r)

    t1 = p.add_table(rows=0, cols=4)
    one(t1, "Альфа")
    one(t1, "Поликлиника | Врач на дом")
    clinic(t1, 'Клиника А (ООО "Клиника А")', True, "Московская область, Химки, ул. Ленина, д.1", "П1")
    clinic(t1, "", True, "Москва, ул. Тверская, д.2", "(П1)")
    one(t1, "^^^^^ Внимание предыдущая клиника: только взрослое отделение.")
    one(t1, "Стоматология")
    clinic(t1, 'АО "Зуб" (ФРАНШИЗА 10%)', False, "Москва, ул. Зубная, д.3", "С1_фр")
    legend(t1)

    alpha_text = "\n".join([
        "Программа добровольного медицинского страхования «Антиклещ» (далее – Программа):",
        "По настоящей Программе страховыми случаями являются:",
        "1. В рамках Программы гарантируется:",
        "1.1. Первичный осмотр врача.",
        "1.4. При невозможности исследования клеща: исследование крови.",
        "Программа стоматологического обслуживания «Бизнес»:",
        "Программа включает:",
        "1. Терапевтическая стоматологическая помощь в объеме:",
        "1.4. Снятие твердых зубных отложений (ТЗО) ультразвуковым и ручным методом однократно.",
        "1.5. Снятие зубного налета методом AIR FLOW (в дополнение к п.п.1.4) однократно.",
        "Исключения из программы:",
        "1. Замена пломб в косметических целях.",
        FILLER * 3,
    ])
    t2 = p.add_table(rows=0, cols=4)
    one(t2, alpha_text)
    # ловушка «таблица ≠ программа»: перечень «Беты» начинается внутри таблицы с текстом «Альфы»
    one(t2, "Бета")
    one(t2, "Поликлиника")
    clinic(t2, 'ООО "Бета-Мед"', True, "Пермский край, Пермь, ул. Мира, д.5", "016_5301П")
    clinic(t2, 'ООО "Бета-Лаб"', False, "Все адреса ЛП, работающих в рамках ДМС", "ЛАБ")
    legend(t2)

    beta_text = "\n".join([
        "Программа добровольного медицинского страхования «Антиклещ» (далее – Программа):",
        "1. В рамках Программы гарантируется:",
        "1.1. Первичный осмотр врача.",
        "Помощь путешествующим по России:",
        "Объем неотложной помощи: амбулаторно-поликлиническая, стационарная и стоматологическая помощь.",
        # вид помощи есть в тексте условий, а в перечне «Беты» его нет → present=True по тексту (ревизия волны 1)
        "Вызов врача на дом в пределах административных границ города:",
        "Помощь на дому включает в себя осмотр врача.",
        # ловушка: вид помощи назван только в заголовке исключений → это не «входит»
        "Исключения из страхового покрытия по стоматологической помощи:",
        "1. Замена пломб.",
        FILLER * 3,
    ])
    t3 = p.add_table(rows=0, cols=4)
    one(t3, beta_text)

    p.add_paragraph("______________________")
    p.add_paragraph("Расширения к холдингу:")
    p.add_paragraph("Бонусный Цифровой чек-ап в лаборатории")
    p.save(folder / "Приложение 1. Программа ДМС.docx")

    files = []
    for name, dtype in (("Договор № 99.docx", "contract"), ("Приложение 1. Программа ДМС.docx", "program")):
        f = folder / name
        files.append(KitFile(path=str(f.relative_to(tmp)), title=f.stem, fmt="docx", doc_type=dtype,
                             scope="contract", size=f.stat().st_size, sha256="0" * 64))
    return KitContract(id="c99", group_id="gk9", legal_entity="Компания 99", files=files), tmp
